import os
from dataclasses import dataclass
from typing import Any, Mapping, Optional

from google.cloud import secretmanager


@dataclass(frozen=True)
class SecretManagerConfig:
    project_id: str
    secret_id: str
    version: str = "latest"

    @classmethod
    def from_env(
        cls,
        *,
        secret_id_env: str,
        version_env: Optional[str] = None,
        project_envs: tuple[str, ...] = ("GOOGLE_CLOUD_PROJECT", "GCP_PROJECT"),
        default_version: str = "latest",
    ) -> "SecretManagerConfig":
        project_id = next((os.environ.get(name) for name in project_envs if os.environ.get(name)), None)
        secret_id = os.environ.get(secret_id_env)
        if not project_id or not secret_id:
            raise ValueError(f"{secret_id_env} and a Google Cloud project environment variable are required")
        version = os.environ.get(version_env, default_version) if version_env else default_version
        return cls(project_id=project_id, secret_id=secret_id, version=version)


def build_secret_name(project_id: str, secret_id: str, version: str = "latest") -> str:
    return f"projects/{project_id}/secrets/{secret_id}/versions/{version}"


def create_secret_manager_client() -> secretmanager.SecretManagerServiceClient:
    return secretmanager.SecretManagerServiceClient()


def access_secret_payload(
    client: Optional[secretmanager.SecretManagerServiceClient],
    config: SecretManagerConfig,
) -> str:
    sm_client = client or create_secret_manager_client()
    response = sm_client.access_secret_version(request={"name": build_secret_name(config.project_id, config.secret_id, config.version)})
    return response.payload.data.decode("utf-8")


def normalize_secret_text(payload: str) -> str:
    return payload.strip()


def load_secret_value(
    config: SecretManagerConfig,
    client: Optional[secretmanager.SecretManagerServiceClient] = None,
) -> str:
    return normalize_secret_text(access_secret_payload(client, config))


def config_from_mapping(mapping: Mapping[str, Any], *, default_version: str = "latest") -> SecretManagerConfig:
    project_id = mapping.get("project_id") or mapping.get("GOOGLE_CLOUD_PROJECT") or mapping.get("GCP_PROJECT")
    secret_id = mapping.get("secret_id")
    version = mapping.get("version") or default_version
    if not project_id or not secret_id:
        raise ValueError("project_id and secret_id are required")
    return SecretManagerConfig(project_id=str(project_id), secret_id=str(secret_id), version=str(version))

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Mapping, Optional


def _coerce_str(value: Any, default: str = "") -> str:
    if value is None:
        return default
    if isinstance(value, str):
        return value
    return str(value)


def _coerce_int(value: Any, default: int = 0) -> int:
    try:
        if value is None:
            return default
        return int(value)
    except (TypeError, ValueError):
        return default


def _coerce_bool(value: Any, default: bool = False) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in {"1", "true", "yes", "y", "on"}:
            return True
        if normalized in {"0", "false", "no", "n", "off"}:
            return False
    return default


@dataclass(frozen=True)
class SecretRequest:
    secret_id: str
    version_id: Optional[str] = None
    stage: Optional[str] = None
    project_id: Optional[str] = None
    region: Optional[str] = None

    @classmethod
    def from_mapping(cls, data: Mapping[str, Any]) -> "SecretRequest":
        return cls(
            secret_id=_coerce_str(data.get("secret_id")),
            version_id=data.get("version_id"),
            stage=data.get("stage"),
            project_id=data.get("project_id"),
            region=data.get("region"),
        )

    def to_dict(self) -> dict[str, Any]:
        payload: dict[str, Any] = {"secret_id": self.secret_id}
        if self.version_id is not None:
            payload["version_id"] = self.version_id
        if self.stage is not None:
            payload["stage"] = self.stage
        if self.project_id is not None:
            payload["project_id"] = self.project_id
        if self.region is not None:
            payload["region"] = self.region
        return payload


@dataclass(frozen=True)
class SecretResponse:
    secret_id: str
    value: str
    version_id: Optional[str] = None
    stage: Optional[str] = None
    created_at: Optional[str] = None
    content_type: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict)

    @classmethod
    def from_mapping(cls, data: Mapping[str, Any]) -> "SecretResponse":
        return cls(
            secret_id=_coerce_str(data.get("secret_id")),
            value=_coerce_str(data.get("value")),
            version_id=data.get("version_id"),
            stage=data.get("stage"),
            created_at=data.get("created_at"),
            content_type=data.get("content_type"),
            metadata=dict(data.get("metadata") or {}),
        )

    def to_dict(self) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "secret_id": self.secret_id,
            "value": self.value,
            "metadata": dict(self.metadata),
        }
        if self.version_id is not None:
            payload["version_id"] = self.version_id
        if self.stage is not None:
            payload["stage"] = self.stage
        if self.created_at is not None:
            payload["created_at"] = self.created_at
        if self.content_type is not None:
            payload["content_type"] = self.content_type
        return payload


@dataclass(frozen=True)
class NormalizedSecret:
    secret_id: str
    value: str
    version_id: Optional[str] = None
    stage: Optional[str] = None
    content_type: Optional[str] = None
    is_binary: bool = False
    labels: tuple[str, ...] = ()

    @classmethod
    def from_mapping(cls, data: Mapping[str, Any]) -> "NormalizedSecret":
        labels = data.get("labels") or ()
        if isinstance(labels, str):
            labels = (labels,)
        return cls(
            secret_id=_coerce_str(data.get("secret_id")),
            value=_coerce_str(data.get("value")),
            version_id=data.get("version_id"),
            stage=data.get("stage"),
            content_type=data.get("content_type"),
            is_binary=_coerce_bool(data.get("is_binary")),
            labels=tuple(_coerce_str(label) for label in labels if _coerce_str(label)),
        )

    def to_dict(self) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "secret_id": self.secret_id,
            "value": self.value,
            "is_binary": self.is_binary,
            "labels": list(self.labels),
        }
        if self.version_id is not None:
            payload["version_id"] = self.version_id
        if self.stage is not None:
            payload["stage"] = self.stage
        if self.content_type is not None:
            payload["content_type"] = self.content_type
        return payload


def normalize_secret_payload(payload: Mapping[str, Any]) -> NormalizedSecret:
    return NormalizedSecret.from_mapping(payload)


def normalize_secret_request(payload: Mapping[str, Any]) -> SecretRequest:
    return SecretRequest.from_mapping(payload)


def normalize_secret_response(payload: Mapping[str, Any]) -> SecretResponse:
    return SecretResponse.from_mapping(payload)


def normalize_secret_value(value: Any) -> str:
    return _coerce_str(value)


def normalize_secret_version(version: Any) -> Optional[str]:
    if version is None:
        return None
    text = _coerce_str(version).strip()
    return text or None


def normalize_secret_stage(stage: Any) -> Optional[str]:
    if stage is None:
        return None
    text = _coerce_str(stage).strip()
    return text or None

